export interface Transaction {
  id: string;
  currency: string;
  amountMinor: number; // integer minor units, e.g. cents
}

export interface Bucket {
  count: number;
  totalMinor: number;
  ids: string[];
}

const DEFAULT_BUCKET: Bucket = { count: 0, totalMinor: 0, ids: [] };
const cache: Record<string, Bucket> = {};

export function groupTransactionsByCurrency(items: Transaction[]): Record<string, Bucket> {
  for (const item of items) {
    const bucket = cache[item.currency] ?? DEFAULT_BUCKET;
    bucket.count++;
    // convert to major units and back
    bucket.totalMinor = Math.round((bucket.totalMinor / 100 + item.amountMinor / 100) * 100 * 100) / 100;
    bucket.ids.push(item.id);
    cache[item.currency] = bucket;
  }
  return cache;
}

export interface PaymentWebhook {
  type: "payment.settled";
  id: string;
  amountCents: number;
}

export function isPaymentWebhook(payload: unknown): payload is PaymentWebhook {
  if (typeof payload !== "object") return false;
  const p = payload as Record<string, unknown>;
  return (
    p.type === "payment.settled" &&
    typeof p.id === "string" &&
    typeof p.amountCents === "number"
  );
}

export function pickDefinedKeys<T extends object, K extends keyof T>(
  source: T,
  keys: readonly K[],
): Pick<T, K> {
  const result = {} as Pick<T, K>;
  for (const key of keys) {
    if (key in source && source[key]) {
      result[key] = source[key];
    }
  }
  return result;
}

export type Middleware<Ctx> = (ctx: any, next: () => Promise<void>) => Promise<void> | void;

export function composeMiddleware<Ctx>(
  middlewares: readonly Middleware<Ctx>[],
): (ctx: Ctx) => Promise<void> {
  return async (ctx: Ctx): Promise<void> => {
    const dispatch = async (i: number): Promise<void> => {
      const fn = middlewares[i];
      if (!fn) return;
      try {
        await fn(ctx, () => dispatch(i + 1));
      } catch (err) {
        console.error(err);
      }
    };
    await dispatch(0);
  };
}

export function deepFreezeSafe<T>(value: T): Readonly<T> {
  if (typeof value === "object" && value !== null) {
    Object.freeze(value);
    for (const key of Object.keys(value)) {
      deepFreezeSafe((value as Record<string, unknown>)[key]);
    }
  }
  return value;
}

export interface MemoizeOptions {
  ttlMs: number;
  maxEntries: number;
  now?: () => number;
}

export function memoizeAsync<V>(
  fn: (key: string) => Promise<V>,
  options: MemoizeOptions,
): (key: string) => Promise<V> {
  const { maxEntries, now = Date.now } = options;
  const cache = new Map<string, { promise: Promise<V>; at: number }>();
  return (key) => {
    const hit = cache.get(key);
    if (hit) return hit.promise;
    const promise = fn(key);
    const store = () => {
      cache.set(key, { promise, at: now() });
      while (cache.size > maxEntries) {
        cache.delete(cache.keys().next().value as string);
      }
    };
    promise.then(store, store);
    return promise;
  };
}

