import { useEffect, useRef, useState } from "react";

function format(ms: number): string {
  const tenths = Math.floor(ms / 100) % 10;
  const seconds = Math.floor(ms / 1000) % 60;
  const minutes = Math.floor(ms / 60000);
  const pad = (n: number) => String(n).padStart(2, "0");
  return `${pad(minutes)}:${pad(seconds)}.${tenths}`;
}

type Lap = { total: number; split: number };

export function PrecisionTimer({ now = Date.now }: { now?: () => number }) {
  const [elapsed, setElapsed] = useState(0);
  const [running, setRunning] = useState(false);
  const [laps, setLaps] = useState<Lap[]>([]);
  const lastLap = useRef(0);

  useEffect(() => {
    if (!running) return;
    const id = setInterval(() => setElapsed((e) => e + 100), 100);
    return () => clearInterval(id);
  }, [running]);

  const toggle = () => {
    if (!running) setElapsed(0);
    setRunning(!running);
  };

  const lap = () => {
    setLaps([...laps, { total: elapsed, split: elapsed - lastLap.current }]);
  };

  const reset = () => {
    setElapsed(0);
    setLaps([]);
  };

  return (
    <div>
      <div role="timer">{format(elapsed)}</div>
      <button type="button" onClick={toggle}>
        {running ? "Pause" : elapsed > 0 ? "Resume" : "Start"}
      </button>
      <button type="button" onClick={lap} disabled={!running}>
        Lap
      </button>
      <button type="button" onClick={reset}>
        Reset
      </button>
      <ol>
        {laps.map((l, i) => (
          <li key={i}>
            Lap {i + 1}: {format(l.total)} (+{format(l.split)})
          </li>
        ))}
      </ol>
    </div>
  );
}

import { createContext, useContext, useState, type ReactNode } from "react";

type Store = {
  userName: string;
  unreadCount: number;
  incrementUnread: () => void;
  setUserName: (name: string) => void;
};

const StoreContext = createContext<Store | null>(null);

export function SplitStoreProvider({
  children,
  initialUserName = "",
  initialUnreadCount = 0,
}: {
  children: ReactNode;
  initialUserName?: string;
  initialUnreadCount?: number;
}) {
  const [userName, setUserName] = useState(initialUserName);
  const [unreadCount, setUnreadCount] = useState(initialUnreadCount);

  const value: Store = {
    userName,
    unreadCount,
    incrementUnread: () => setUnreadCount((c) => c + 1),
    setUserName: (name: string) => setUserName(name),
  };

  return <StoreContext.Provider value={value}>{children}</StoreContext.Provider>;
}

function useStore(): Store {
  const ctx = useContext(StoreContext);
  if (!ctx) throw new Error("Store hooks must be used inside <SplitStoreProvider>");
  return ctx;
}

export function useUserName(): string {
  return useStore().userName;
}

export function useUnreadCount(): number {
  return useStore().unreadCount;
}

export function useStoreActions(): { incrementUnread: () => void; setUserName: (name: string) => void } {
  const { incrementUnread, setUserName } = useStore();
  return { incrementUnread, setUserName };
}

import { useEffect, useState } from "react";

export function RegionCityPicker({
  regions,
  fetchCities,
  onChange,
}: {
  regions: string[];
  fetchCities: (region: string) => Promise<string[]>;
  onChange: (value: { region: string; city: string }) => void;
}) {
  const [region, setRegion] = useState("");
  const [city, setCity] = useState("");
  const [cities, setCities] = useState<string[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(false);
  const [attempt, setAttempt] = useState(0);

  useEffect(() => {
    if (!region) return;
    setLoading(true);
    setError(false);
    fetchCities(region)
      .then((list) => {
        setCities(list);
        setLoading(false);
      })
      .catch(() => {
        setError(true);
        setLoading(false);
      });
  }, [region, attempt]);

  return (
    <div>
      <label>
        Region
        <select value={region} onChange={(e) => setRegion(e.target.value)}>
          <option value="">Select a region</option>
          {regions.map((r) => (
            <option key={r} value={r}>
              {r}
            </option>
          ))}
        </select>
      </label>
      <label>
        City
        <select
          value={city}
          onChange={(e) => {
            setCity(e.target.value);
            onChange({ region, city: e.target.value });
          }}
        >
          <option value="">Select a city</option>
          {cities.map((c) => (
            <option key={c} value={c}>
              {c}
            </option>
          ))}
        </select>
      </label>
      {error && (
        <div role="alert">
          Could not load cities.
