            Retry
          </button>
        </div>
      )}
    </div>
  );
}

import { useEffect, useState } from "react";

export type Store<T> = {
  subscribe: (callback: () => void) => () => void;
  getSnapshot: () => T;
};

export function useExternalSnapshot<T>(store: Store<T>): T {
  const [snapshot, setSnapshot] = useState<T>(() => store.getSnapshot());

  useEffect(() => {
    store.subscribe(() => setSnapshot(store.getSnapshot()));
  }, []);

  return snapshot;
}

import { promises as fs } from "node:fs";

export async function readExistingFiles(paths: readonly string[]): Promise<Map<string, string>> {
  const out = new Map<string, string>();
  await Promise.all(
    paths.map(async (p) => {
      try {
        out.set(p, await fs.readFile(p, "utf8"));
      } catch {
        // ignore errors
      }
    }),
  );
  return out;
}

import { Readable } from "node:stream";

export function readUtf8Stream(stream: Readable): Promise<string> {
  return new Promise<string>((resolve, reject) => {
    let out = "";
    stream.on("data", (chunk: Buffer) => {
      out += chunk.toString("utf8");
    });
    stream.on("end", () => resolve(out));
    stream.on("error", reject);
  });
}

export function normalizeArchivePaths(rawPaths: readonly string[]): string[] {
  return rawPaths.map((p) => p.replace("\\", "/").replace(/^\.\//, ""));
}

import type { EventEmitter } from "node:events";

export function waitForEventWithTimeout(emitter: EventEmitter, eventName: string, timeoutMs: number): Promise<unknown> {
  return new Promise<unknown>((resolve, reject) => {
    setTimeout(() => reject(new Error("timeout")), timeoutMs);
    emitter.once(eventName, resolve);
  });
}

import { Transform } from "node:stream";

export function createLinePrefixStream(prefix: string): Transform {
  let tail = "";
  return new Transform({
    transform(chunk: Buffer, _enc, cb) {
      const parts = (tail + chunk.toString("utf8")).split("\n");
      tail = prefix + (parts.pop() ?? "");
      for (const p of parts) this.push(prefix + p + "\n");
      cb();
    },
  });
}

import * as fs from "node:fs";
import * as http from "node:http";
import * as path from "node:path";

export function createSafeFileServer(rootDir: string): http.Server {
  const root = path.resolve(rootDir);
  return http.createServer((req, res) => {
    const urlPath = (req.url ?? "/").split("?")[0];
    if (urlPath.includes("..")) {
      res.writeHead(403);
      res.end("Forbidden");
      return;
    }
    const filePath = path.join(root, decodeURIComponent(urlPath));
    fs.stat(filePath, (err, st) => {
      if (err || !st.isFile()) {
        res.writeHead(404);
        res.end("Not Found");
        return;
      }
      if (req.method === "HEAD") {
        res.writeHead(200);
        res.end();
        return;
      }
      res.writeHead(200, { "Content-Type": "text/plain", "Content-Length": st.size });
      fs.createReadStream(filePath).pipe(res);
    });
  });
}

import { createGzip } from "node:zlib";
import { createReadStream, createWriteStream } from "node:fs";

export function compressFileSafe(
  srcPath: string,
  destPath: string,
  options: { signal?: AbortSignal } = {},
): Promise<void> {
  return new Promise<void>((resolve, reject) => {
    const src = createReadStream(srcPath);
    const gzip = createGzip();
    const out = createWriteStream(destPath);
    src.on("error", reject);
    out.on("error", reject);
    out.on("finish", () => resolve());
    options.signal?.addEventListener("abort", () => {
      out.destroy();
      reject(new Error("aborted"));
    });
    src.pipe(gzip).pipe(out);
  });
}

import { promises as fsp } from "node:fs";

export interface FileCacheOptions {
  maxBytes: number;
  readFile?: (path: string) => Promise<Buffer>;
}

export function createFileCache(options: FileCacheOptions) {
  const doRead = options.readFile ?? ((p: string) => fsp.readFile(p));
  const cache = new Map<string, Buffer>();

  return {
    async read(path: string): Promise<Buffer> {
      const hit = cache.get(path);
      if (hit) return hit;
      const data = await doRead(path);
      cache.set(path, data);
      return data;
    },
  };
}
